using System;
using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;

namespace Media.DBContext.Models;

/// <summary>
/// Represents the filters of a shared search, which are referenced by the short token of a share link.
/// </summary>
[Table("share_queries")]
public class ShareQuery
{
  /// <summary>
  /// Primary key. Autogenerated.
  /// </summary>
  [Key]
  public Guid ShareQueryId { get; set; }

  /// <summary>
  /// The token the link refers to.
  /// </summary>
  [Required]
  public string Token { get; set; } = null!;

  /// <summary>
  /// SHA-256 hash of the canonical filters, so equal searches share the same token.
  /// </summary>
  [Required]
  public string QueryHash { get; set; } = null!;

  /// <summary>
  /// The canonical filters as json.
  /// </summary>
  [Required]
  public string Query { get; set; } = null!;

  /// <summary>
  /// Date when the token was created.
  /// </summary>
  public DateTime CreatedAt { get; set; }

  /// <summary>
  /// Date when the token was created or resolved the last time.
  /// </summary>
  public DateTime LastUsedAt { get; set; }
}
